    nav_edit_entries: "{n} Einträge",
    nav_sheet_empty: "Die Schublade ist leer — ohne Kacheln, Karten oder Titel gibt es nichts aufzuziehen. Die Leiste wird deshalb als schwebende Leiste gezeichnet. Unter „Sheet“ Kacheln hinzufügen oder ein bestehendes Untermenü übernehmen.",
