    editor_nav_badge_source_template: "Template",
    editor_nav_submenu_hint: "Klappt beim Antippen ein kleines Menü über der Leiste auf. Für Seiten, die man selten braucht. Wer ein aufziehbares Sheet nutzt, legt sie besser dort hinein.",
    editor_nav_action_hint_submenu: "Dieser Eintrag hat ein Untermenü — ein Tipp öffnet es. Eine eigene Tap-Aktion ist nur nötig, wenn er stattdessen etwas anderes tun soll.",
    editor_nav_different_widths: "Handy und Desktop getrennt einstellen",
    editor_nav_different_widths_hint: "Aus: eine Einstellung gilt überall — für die meisten Dashboards richtig. An: darunter erscheinen zwei Blöcke, in denen Variante, Breite und Beschriftungen für schmale und breite Ansichten getrennt gesetzt werden. Typisch ist Kopfzeile am Desktop und Fußzeile oder Sheet am Handy. Was in einem Block leer bleibt, übernimmt den Wert von oben.",
    editor_nav_intro: "Eine Navigationsleiste für dein Dashboard. Unten legst du fest, welche Seiten sie enthält und wie sie aussieht.",
